MOD=998244353
def count_sc(n,s):
    length=2*n
    dp={(0,0):1} # (B_unmatched, U_unmatched)
    for idx,ch in enumerate(s,1):
        nd={}
        for (B,U),ways in dp.items():
            if ch=='B':
                # leave unmatched
                key=(B+1,U)
                nd[key]=(nd.get(key,0)+ways)%MOD
                # match to waiting white
                if U>0:
                    key=(B,U-1)
                    nd[key]=(nd.get(key,0)+ways*U)%MOD
            else:
                # match to unmatched black
                if B>0:
                    key=(B-1,U)
                    nd[key]=(nd.get(key,0)+ways*B)%MOD
                # defer
                key=(B,U+1)
                nd[key]=(nd.get(key,0)+ways)%MOD
        if idx<length:
            dp={k:v for k,v in nd.items() if k[0]>=1}
        else:
            dp=nd
    return dp.get((0,0),0)
