import itertools, math
MOD=10**9+7
def formula(n,m,k):
    r=n-k
    if r<=0: return 0
    if m==1: return 1 if r==1 else 0
    return (math.comb(n-1, r-1)%MOD) * (m%MOD) * pow(m-1, r-1, MOD) % MOD

def brute(n,m,k):
    cnt=0
    for arr in itertools.product(range(1,m+1), repeat=n):
        eq=sum(arr[i]==arr[i-1] for i in range(1,n))
        if eq==k:
            cnt+=1
    return cnt%MOD

for n in range(1,6):
    for m in range(1,4):
        for k in range(0,n):
            f=formula(n,m,k)
            b=brute(n,m,k)
            if f!=b:
                print('mismatch',n,m,k,f,b)
