from functools import lru_cache

def card_game_winner_bruteforce(n,cards):
    @lru_cache(None)
    def win(mask):
        # list bits
        bits=[i for i in range(n) if mask>>i &1]
        for idx_i in range(len(bits)):
            i=bits[idx_i]
            for j in bits[idx_i+1:]:
                if cards[i][0]==cards[j][0] or cards[i][1]==cards[j][1]:
                    newmask=mask & ~(1<<i) & ~(1<<j)
                    if not win(newmask):
                        return True
        return False
    full=(1<<n)-1
    return 'Takahashi' if win(full) else 'Aoki'

